    // Pre-condition: Initiate cooldown
    locking.initiateCooldown(depositAmount);
    // Snapshot of cooldown info
    (uint256 initialDeposit, uint256 initialCooldownStart, uint256 initialCooldownAmount) = locking.getCoolDownInfo(address(this));
    assert(initialCooldownAmount == depositAmount);
    // First withdrawal
    try locking.withdraw() {
        assert(true);  // First withdrawal should succeed
    } catch {
        assert(false);  // Should not revert here
    }
