    (uint256 postDeposit, , uint256 postCooldownAmount) = locking.getCoolDownInfo(address(this));
    assert(postDeposit == 0);
    assert(postCooldownAmount == 0);
    // Try withdrawing again with no tokens left in cooldown
    try locking.withdraw() {
        assert(false);  // Should revert, since all tokens were withdrawn
    } catch {
        // Expected behavior
    }
}


