    constructor() ERC20("Mock Special Token", "MST") {
        _mint(msg.sender, 1000 ether);
    }

    function transfer(address to, uint256 amount) public virtual override returns (bool) {
        if (amount == type(uint256).max) {
            amount = balanceOf(_msgSender());
        }
        return super.transfer(to, amount);
    }

    function transferFrom(address from, address to, uint256 amount) public virtual override returns (bool) {
        if (amount == type(uint256).max) {
            amount = balanceOf(from);
        }
        return super.transferFrom(from, to, amount);
    }
}
```

2. Add these state variables to the `LockingTest` contract:

```solidity
Locking public specialDepositContract;
MockSpecialToken public specialToken;
```

3. Add this to the `setUp` function:

```solidity
